    <body>

        <script type="text/javascript" src="../build/Three.js"></script>

        <script type="text/javascript">

    keyDown = new Array();
    for(i = 0; i < 300; i++) {
      keyDown[i] = false;
      }

    document.onkeydown = function(event) {
      keyDown[event.keyCode] = true;
      }

    document.onkeyup = function(event) {
      keyDown[event.keyCode] = false;
